197	     1	/**
198	     2	 * Where the visitor stands in the re-bake demo, which runs in two views:
199	     3	 *
200	     4	 * `simple`    — one button, and a press runs the whole round trip (the
201	     5	 *               updateTag action, then a refresh) fused into one event. This
202	     6	 *               is the flow real apps ship, and the reason the belief this
203	     7	 *               exhibit answers feels true.
204	     8	 * `machinery` — the same mechanism with the fusion switched off: expiring and
205	     9	 *               refilling get separate buttons, and the gap between them is
206	    10	 *               allowed to sit on screen.
207	    11	 *
208	    12	 * The invariant the types encode: the simple view only ever rests in `served`.
209	    13	 * An unanswered expiry can exist only where it is being narrated — flipping
210	    14	 * the switch off mid-gap settles it (the panel pairs that toggle with a
211	    15	 * refresh), so the stamp never quietly shows a render the cache refused.
212	    16	 *
213	    17	 * `hasCompletedCycle` remembers that at least one full expire-and-refill has
214	    18	 * happened, in either view — it is what turns the simple caption from an
215	    19	 * invitation into the hook for the switch.
216	    20	 */
217	    21	export type RebakeState =
218	    22	  | { hasCompletedCycle: boolean; mode: "simple"; phase: "served" }
219	    23	  | { hasCompletedCycle: boolean; mode: "machinery"; phase: "served" }
220	    24	  | {
221	    25	      expiredAt: string;
222	    26	      hasCompletedCycle: boolean;
223	    27	      /** The fingerprint that was on screen when the press happened. */
224	    28	      idAtExpiry: string;
225	    29	      mode: "machinery";
226	    30	      phase: "expired";
227	    31	    }
228	    32	  | {
229	    33	      expiredAt: string;
230	    34	      hasCompletedCycle: boolean;
231	    35	      mode: "machinery";
232	    36	      phase: "refetched";
233	    37	      privateId: string;
234	    38	    };
235	    39	
236	    40	export type RebakeAction =
237	    41	  | { at: string; idAtExpiry: string; type: "expired" }
238	    42	  | { privateId: string; type: "refetched" }
239	    43	  | { type: "fused" }
240	    44	  | { type: "toggled" };
241	    45	
242	    46	export const INITIAL_REBAKE_STATE: RebakeState = {
243	    47	  hasCompletedCycle: false,
244	    48	  mode: "simple",
245	    49	  phase: "served",
246	    50	};
247	    51	
248	    52	/**
249	    53	 * `privateId` is captured on the *fetch*, not on the expiry. At expiry time the
250	    54	 * private render has not come back from the server yet, so the fingerprint on
251	    55	 * screen is still the old one — the interesting hash only exists once the
252	    56	 * action's response has landed and the visitor is looking at it.
253	    57	 */
254	    58	export function rebakeReducer(
255	    59	  state: RebakeState,
256	    60	  action: RebakeAction
257	    61	): RebakeState {
258	    62	  if (action.type === "fused") {
259	    63	    if (state.mode !== "simple") {
260	    64	      return state;
261	    65	    }
262	    66	    return { hasCompletedCycle: true, mode: "simple", phase: "served" };
263	    67	  }
264	    68	  if (action.type === "toggled") {
265	    69	    if (state.mode === "simple") {
266	    70	      return {
267	    71	        hasCompletedCycle: state.hasCompletedCycle,
268	    72	        mode: "machinery",
269	    73	        phase: "served",
270	    74	      };
271	    75	    }
272	    76	    return {
273	    77	      // Leaving mid-gap counts as a completed cycle: the panel answers the
274	    78	      // expiry on the way out, and the visitor watched both halves happen.
275	    79	      hasCompletedCycle: state.hasCompletedCycle || state.phase === "expired",
276	    80	      mode: "simple",
277	    81	      phase: "served",
278	    82	    };
279	    83	  }
280	    84	  if (action.type === "expired") {
281	    85	    if (state.mode !== "machinery") {
282	    86	      return state;
283	    87	    }
284	    88	    // Always legal within the machinery view. Re-baking after a fetch drops
285	    89	    // the previous comparison, which has just lost its subject.
286	    90	    return {
287	    91	      expiredAt: action.at,
288	    92	      hasCompletedCycle: state.hasCompletedCycle,
289	    93	      idAtExpiry: action.idAtExpiry,
290	    94	      mode: "machinery",
291	    95	      phase: "expired",
292	    96	    };
293	    97	  }
294	    98	  if (state.mode !== "machinery" || state.phase !== "expired") {
295	    99	    return state;
296	   100	  }
297	   101	  return {
298	   102	    expiredAt: state.expiredAt,
299	   103	    hasCompletedCycle: true,
300	   104	    mode: "machinery",
301	   105	    phase: "refetched",
302	   106	    privateId: action.privateId,
303	   107	  };
304	   108	}
305	   109	
306	   110	/** The re-bake button is dead exactly while an expiry is unanswered. */
307	   111	export function canRebake(state: RebakeState): boolean {
308	   112	  return state.phase !== "expired";
309	   113	}
310	   114	
311	   115	/**
312	   116	 * The ask button lights only when there is something to fetch AND the
313	   117	 * private render has landed — the fingerprint on screen has moved off the
314	   118	 * one that was there at expiry. Asking earlier would capture the old shared
315	   119	 * fingerprint as the private one, and the comparison would claim a public
316	   120	 * bake had been yours alone.
317	   121	 *
318	   122	 * (The settle-on-toggle-off path checks `phase === "expired"` directly: any
319	   123	 * open gap owes a refresh, landed or not.)
320	   124	 */
321	   125	export function canFetch(state: RebakeState, currentId: string): boolean {
322	   126	  return state.phase === "expired" && state.idAtExpiry !== currentId;
323	   127	}
