     3	import { cookies, headers } from "next/headers";
     4	import { COUNT_COOKIE, MAX_COUNT, parseCount } from "./count-parser";
     5	
     6	const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365;
     7	
     8	/**
     9	 * What the action saw and did, read from the real request — the request
    10	 * view draws this and nothing else. Every field is something the function
    11	 * can only know because the round trip happened: the action id arrives as
    12	 * a header, the body's content type arrives as a header, and the cookie
    13	 * line is the exact one the response carries back.
    14	 */
    15	export interface PressReceipt {
    16	  /** The `Next-Action` header: the function's id, which is the whole route. */
    17	  actionId: string;
    18	  /** The `Content-Type` the browser chose for the form body. */
    19	  contentType: string;
    20	  /** The count after this press. */
    21	  count: number;
    22	  /** The path the POST went to — the page's own. */
    23	  path: string;
    24	  /** The `Set-Cookie` line the response carries, as set. */
    25	  setCookie: string;
    26	}
    27	
    28	/**
    29	 * The entire backend of the mutation demo. No API route, no fetch, no JSON —
    30	 * the form invokes this function on the server, the server rewrites the
    31	 * cookie, and Next.js re-renders the page so every Server Component reading
    32	 * that cookie shows the new value. The signature matches what
    33	 * `useActionState` passes: (previousState, formData). It returns its
    34	 * receipt so the request view can show the round trip that actually ran.
    35	 */
    36	export async function pressTheButton(
    37	  _previous: PressReceipt | null,
    38	  _formData: FormData
    39	): Promise<PressReceipt> {
    40	  const [jar, incoming] = await Promise.all([cookies(), headers()]);
    41	  const count = Math.min(
    42	    parseCount(jar.get(COUNT_COOKIE)?.value) + 1,
    43	    MAX_COUNT
    44	  );
    45	
    46	  const options = {
    47	    httpOnly: true,
    48	    maxAge: ONE_YEAR_SECONDS,
    49	    path: "/",
    50	    sameSite: "lax",
    51	  } as const;
    52	  jar.set(COUNT_COOKIE, String(count), options);
    53	
    54	  return {
    55	    actionId: incoming.get("next-action") ?? "",
    56	    contentType: (incoming.get("content-type") ?? "").split(";")[0],
    57	    count,
    58	    path: pathnameOf(incoming.get("referer")),
    59	    setCookie: `${COUNT_COOKIE}=${count}; Path=${options.path}; Max-Age=${options.maxAge}; HttpOnly; SameSite=Lax`,
    60	  };
    61	}
    62	
    63	/** The page's own path, from the referer the browser sends with the POST. */
    64	function pathnameOf(referer: string | null): string {
    65	  if (!referer) {
    66	    return "";
    67	  }
    68	  try {
    69	    return new URL(referer).pathname;
    70	  } catch {
    71	    return "";
    72	  }
    73	}
