     1	export const COUNT_COOKIE = "playground-presses";
     2	export const MAX_COUNT = 9999;
     3	
     4	/**
     5	 * A cookie is visitor-editable storage, so the value is parsed like it was
     6	 * typed by a stranger — because it was. Anything that isn't a whole number
     7	 * in range collapses to 0.
     8	 */
     9	const COUNT_PATTERN = /^\d{1,4}$/;
    10	
    11	export function parseCount(raw: string | undefined): number {
    12	  if (!(raw && COUNT_PATTERN.test(raw))) {
    13	    return 0;
    14	  }
    15	  const parsed = Number.parseInt(raw, 10);
    16	  return Math.min(parsed, MAX_COUNT);
    17	}
