     1	"use client";
     2	
     3	import { useEffect, useState } from "react";
     4	
     5	/**
     6	 * The navigation chapter's reading, running before the chapter does: the
     7	 * lab's own contents rows are prefetched by next/link as they scroll into
     8	 * view, so the instrument is the site's own chrome caught doing the thing
     9	 * the chapter will be about.
    10	 *
    11	 * What it counts is real and per-visitor: RSC payload fetches, which is
    12	 * what a prefetch is. Every App Router prefetch appends `_rsc=` to the
    13	 * route it is fetching, so the resource timeline is the instrument — no
    14	 * hooks into the router, nothing the page has to be told.
    15	 *
    16	 * Counted by route, not by request: this build fetches a small shell and
    17	 * then the segment, so five links produce ten entries and a row claiming
    18	 * "10 routes" would be the index's first lie. Bytes are summed across
    19	 * every request, because that is what the visitor actually paid.
    20	 *
    21	 * Prefetching is disabled in `next dev`, so this reads zero there and only
    22	 * tells the truth against a production build. And the trigger is the
    23	 * viewport, not the pointer — the rows prefetch as they scroll past,
    24	 * before anyone hovers anything, which is why the label says nothing
    25	 * about hovering.
    26	 */
    27	export function NavigationIndexValue() {
    28	  const [reading, setReading] = useState({ bytes: 0, routes: 0 });
    29	
    30	  useEffect(() => {
    31	    const routes = new Set<string>();
    32	    const requests = new Set<string>();
    33	    let bytes = 0;
    34	
    35	    const take = (entries: PerformanceEntryList) => {
    36	      for (const entry of entries) {
    37	        if (!entry.name.includes("_rsc=") || requests.has(entry.name)) {
    38	          continue;
    39	        }
    40	        requests.add(entry.name);
    41	        routes.add(new URL(entry.name).pathname);
    42	        bytes += (entry as PerformanceResourceTiming).transferSize;
    43	      }
    44	      setReading({ bytes, routes: routes.size });
    45	    };
    46	
    47	    const observer = new PerformanceObserver((list) => take(list.getEntries()));
    48	    observer.observe({ buffered: true, type: "resource" });
    49	
    50	    return () => observer.disconnect();
    51	  }, []);
    52	
    53	  return (
    54	    <span>
    55	      prefetched for you ·{" "}
    56	      <span className="tabular-nums">{reading.routes}</span>
    57	      {reading.routes === 1 ? " route" : " routes"}
    58	      {reading.bytes > 0 ? (
    59	        <>
    60	          {" · "}
    61	          <span className="tabular-nums">
    62	            {(reading.bytes / 1024).toFixed(1)}
    63	          </span>
    64	          {" kB"}
    65	        </>
    66	      ) : null}
    67	    </span>
    68	  );
    69	}

