     1	"use server";
     2	
     3	import { resend } from "@repo/email";
     4	import ContactTemplate from "@repo/email/templates/contact";
     5	import { parseError } from "@repo/observability/error";
     6	import { headers } from "next/headers";
     7	import { env } from "@/env";
     8	import { clientIp, rateLimiter } from "@/lib/rate-limit";
     9	import { parseContact } from "./schema";
    10	
    11	interface ContactState {
    12	  error?: string;
    13	  success?: boolean;
    14	}
    15	
    16	// A person writes once, maybe twice with a correction. Three an hour per
    17	// caller leaves room for that and not for a loop.
    18	const PER_CALLER = { limit: 3, ms: 1000 * 60 * 60 };
    19	
    20	const MESSAGES = {
    21	  invalid: "Check the three fields: a name, an address that works, a message.",
    22	  limited:
    23	    "That inbox has heard from you a few times already. Try again in an hour.",
    24	  sendFailed:
    25	    "The message didn’t go out. Try again, or write to the address in the footer.",
    26	};
    27	
    28	export const contact = async (
    29	  _prevState: ContactState,
    30	  formData: FormData
    31	): Promise<ContactState> => {
    32	  const input = parseContact(formData);
    33	  if (!input) {
    34	    return { error: MESSAGES.invalid };
    35	  }
    36	
    37	  try {
    38	    const ip = clientIp(await headers());
    39	    if (ip) {
    40	      const limiter = await rateLimiter("contact", PER_CALLER);
    41	      const { success } = await limiter.limit(ip);
    42	      if (!success) {
    43	        return { error: MESSAGES.limited };
    44	      }
    45	    }
    46	
    47	    const { error } = await resend.emails.send({
    48	      from: env.RESEND_FROM,
    49	      react: (
    50	        <ContactTemplate
    51	          email={input.email}
    52	          message={input.message}
    53	          name={input.name}
    54	          sentAt={new Date()}
    55	        />
    56	      ),
    57	      replyTo: input.email,
    58	      subject: `Contact form: ${input.name}`,
    59	      to: env.RESEND_FROM,
    60	    });
    61	
    62	    if (error) {
    63	      // Logged and reported with the provider's wording; the visitor gets
    64	      // a fixed line rather than an API message.
    65	      parseError(error);
    66	      return { error: MESSAGES.sendFailed };
    67	    }
    68	
    69	    return { success: true };
    70	  } catch (error) {
    71	    parseError(error);
    72	    return { error: MESSAGES.sendFailed };
    73	  }
    74	};
